:root {
  /* ========== 色彩体系 ========== */
  /* 県庁の落ち着いたトーン：紺と深緑を基調に、公式感と信頼性を表現 */
  --primary: #1e3a5f;
  --primary-hover: #152847;
  --primary-light: #2d5a8c;

  /* 背景：薄い灰緑で、公共施設の落ち着きを表現 */
  --bg-main: #f0f2f0;
  --bg-card: #e8ebe8;
  --bg-sidebar: #e5e9e5;
  --top-bar-bg: #1e3a5f;

  /* テキスト：濃紺で統一感を保つ */
  --text: #1a1a1a;
  --text-muted: #5a5a5a;

  /* 境界線：薄い紺緑で、カード間の区切りを柔らかく */
  --border: #c5ccc5;
  --top-bar-border: #0f1f2f;

  /* ========== タイポグラフィ ========== */
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Hiragino Sans", "Noto Sans JP", sans-serif;

  /* ========== 寸法・間隔 ========== */
  --space-unit: 8px;
  --control-height: 40px;
  --radius-card: 6px;
  --radius-control: 4px;
  --border-width: 1px;

  /* ========== 影・質感 ========== */
  --shadow-card: 0 2px 8px rgba(30, 58, 95, 0.08);

  /* ========== 質感表現：公文書の紙質感 ========== */
  /* 薄い織目パターンで、公式書類の落ち着きを表現 */
  --surface-texture: 
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 2px,
      rgba(30, 58, 95, 0.02) 2px,
      rgba(30, 58, 95, 0.02) 4px
    ),
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(30, 58, 95, 0.02) 2px,
      rgba(30, 58, 95, 0.02) 4px
    );
  --surface-texture-size: 4px 4px;
  --surface-texture-position: 0 0;

  /* ========== アニメーション ========== */
  --motion-duration: 200ms;

  /* ========== 追加：県庁テイスト用補助色 ========== */
  --accent-success: #2e7d32;
  --accent-warning: #d97706;
  --accent-error: #c92a2a;
  --accent-info: #1976d2;

  /* ========== カード・パネルの微妙な階調 ========== */
  --bg-card-hover: #dfe4df;
  --bg-input: #ffffff;
  --bg-input-disabled: #f5f7f5;

  /* ========== トップバーのテキスト ========== */
  --top-bar-text: #ffffff;
  --top-bar-text-muted: #b0c4de;

  /* ========== ボーダー・ディバイダー ========== */
  --divider-light: #d9dcd9;
  --divider-strong: #b5bdb5;

  /* ========== フォーカス・ハイライト ========== */
  --focus-ring: 0 0 0 3px rgba(30, 58, 95, 0.15);
  --selection-bg: rgba(30, 58, 95, 0.2);
}
